const baseVars = createGlobalThemeContract(base, varName);
const colorVars = createGlobalThemeContract(colorLight, varName);
const scaleVars = createGlobalThemeContract(scaleMedium, varName);

createGlobalTheme(":root", baseVars, base);

// Light is the default. Dark follows the OS unless <html data-theme="light"> pins light.
globalStyle(":root", { vars: assignVars(colorVars, colorLight) });
globalStyle(':root[data-theme="dark"]', { vars: assignVars(colorVars, colorDark) });
globalStyle(':root:not([data-theme="light"])', {
  "@media": { "(prefers-color-scheme: dark)": { vars: assignVars(colorVars, colorDark) } },
});

// Medium is the default. Touch devices take large unless <html data-scale="medium"> pins medium.
globalStyle(":root", { vars: assignVars(scaleVars, scaleMedium) });
globalStyle(':root[data-scale="large"]', { vars: assignVars(scaleVars, scaleLarge) });
globalStyle(':root:not([data-scale="medium"])', {
  "@media": { "(pointer: coarse)": { vars: assignVars(scaleVars, scaleLarge) } },
});

/** Typed references to the CSS variables. Components read semantic tokens only through this. */
export const vars = { ...baseVars, ...colorVars, ...scaleVars };

/** Minimum widths in px, for media queries (CSS variables cannot be used there). */
export const breakpoints = {
  "tablet": 768,
  "desktop": 1024
} as const;
